  position:relative;white-space:nowrap;
}
.tgi-blk_20tiacaz nav.primary a::after{
  content:"";position:absolute;left:14px;right:14px;bottom:7px;height:2px;background:var(--gold);
  transform:scaleX(0);transform-origin:left;transition:transform .2s ease-out;
}
.tgi-blk_20tiacaz nav.primary a:hover::after{transform:scaleX(1);}
.tgi-blk_20tiacaz .mast-side{display:flex;align-items:center;gap:22px;}
.tgi-blk_20tiacaz .mast-tel{font-family:'Source Serif 4',serif;font-size:19px;font-weight:600;color:#fff;text-decoration:none;white-space:nowrap;}
.tgi-blk_20tiacaz .mast-tel small{display:block;font-family:'PT Sans',sans-serif;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--sea-text);margin-top:1px;}
.tgi-blk_20tiacaz .mast-tel:hover{color:var(--gold-bright);}
