@media(max-width:680px){.tgi-blk_20tiacaz .mast-tel{display:none;}}
.tgi-blk_20tiacaz .hero-head .wrap{
  display:grid;grid-template-columns:minmax(0,8fr) minmax(0,4fr);gap:48px;align-items:end;
}
@media(max-width:900px){
  .tgi-blk_20tiacaz .hero-head .wrap{grid-template-columns:1fr;gap:30px;}
}
@keyframes drift-tgi-blk_20tiacaz{from{transform:scale(1.05);}to{transform:scale(1);}}
.tgi-blk_20tiacaz .console .btn{min-height:50px;white-space:nowrap;font-size:16.5px;padding:12px 34px;}
