.tgi-blk_20tiacaz .port-cap .name small{display:block;font-family:'PT Sans',sans-serif;font-weight:700;font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-ink);margin-top:3px;}
