.tgi-blk_20tiacaz .interlude .wrap{position:relative;min-height:270px;display:flex;align-items:center;}
.tgi-blk_20tiacaz footer{background:var(--navy-deep);color:var(--sea-text);font-size:14.5px;border-top:1px solid var(--gold);}
.tgi-blk_20tiacaz footer h3{font-size:13px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-bright);margin-bottom:16px;font-family:'PT Sans',sans-serif;}
